"use client"

import * as React from "react"

import { AppShell } from "@/components/app-shell"
import {
  ModelCatalogPage,
  type CatalogState,
} from "@/components/model-catalog/catalog-page"
import { MockupShell } from "@/components/mockup-shell"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

/**
 * DES-169 — the model catalog, in the shared product chrome.
 *
 * It sits under Configuration beside the other platform-wide admin surfaces,
 * because onboarding a model is a Sarj-staff action whose result every
 * organization inherits. In bulbul that group is the one gated on
 * `hasSuperAdminRole`, which is where this belongs too.
 */
export default function ModelCatalogRoute() {
  const [state, setState] = React.useState<CatalogState>("populated")

  return (
    <MockupShell
      title="Model catalog — onboarding LLM, TTS and STT"
      /* A reviewer control, not a product one: nothing in the app switches a
         page between loaded and failed. Up here it stays out of the design it
         exists to let you check. The states reachable by clicking — no search
         results, a live fetch that timed out, a test that failed — are in the
         page and the dialog themselves. */
      actions={
        <ToggleGroup
          onValueChange={(next) => {
            if (next) setState(next as CatalogState)
          }}
          size="sm"
          type="single"
          value={state}
          variant="outline"
        >
          <ToggleGroupItem value="populated">Populated</ToggleGroupItem>
          <ToggleGroupItem value="empty">Empty</ToggleGroupItem>
          <ToggleGroupItem value="loading">Loading</ToggleGroupItem>
          <ToggleGroupItem value="error">Error</ToggleGroupItem>
        </ToggleGroup>
      }
    >
      <AppShell active="Models">
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          <ModelCatalogPage state={state} />
        </div>
      </AppShell>
    </MockupShell>
  )
}

"use client"

import {
  ArrowDown01Icon,
  BlockGameIcon,
  BookOpen02Icon,
  BubbleChatIcon,
  Building02Icon,
  CallRinging04Icon,
  Chart03Icon,
  ChartColumnIcon,
  CodeIcon,
  DashboardBrowsingIcon,
  DashboardCircleIcon,
  Globe02Icon,
  GoogleDocIcon,
  Key01Icon,
  Message02Icon,
  PlayIcon,
  PlusSignIcon,
  Queue02Icon,
  RoboticIcon,
  Settings01Icon,
  ShieldKeyIcon,
  SmartPhone01Icon,
  CpuIcon,
  TaskDaily01Icon,
  TelephoneIcon,
  VariableIcon,
  VoiceIcon,
  WebhookIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/**
 * Icons for the shared product shell — one glyph per nav destination, matched
 * to the app's own sidebar. Icons *inside* a mockup live in that mockup's own
 * icons.tsx; this file is only the app chrome.
 */
export const PlaygroundIcon = icon(PlayIcon, "PlaygroundIcon")
export const PersonasIcon = icon(RoboticIcon, "PersonasIcon")
export const ScenariosIcon = icon(GoogleDocIcon, "ScenariosIcon")
export const KnowledgeIcon = icon(BookOpen02Icon, "KnowledgeIcon")
export const BatchCallsIcon = icon(Queue02Icon, "BatchCallsIcon")
export const TemplateIcon = icon(DashboardCircleIcon, "TemplateIcon")
export const GlobalPromptsIcon = icon(Globe02Icon, "GlobalPromptsIcon")
export const VoiceLibraryIcon = icon(VoiceIcon, "VoiceLibraryIcon")
export const DashboardIcon = icon(Chart03Icon, "DashboardIcon")
export const ConversationsIcon = icon(CallRinging04Icon, "ConversationsIcon")
export const MessagingIcon = icon(Message02Icon, "MessagingIcon")
export const QualityIcon = icon(DashboardBrowsingIcon, "QualityIcon")
export const ReportsIcon = icon(ChartColumnIcon, "ReportsIcon")
export const TasksIcon = icon(TaskDaily01Icon, "TasksIcon")
export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"

import { toast } from "sonner"

import {
  BackToPickerIcon,
  FetchWarningIcon,
  FieldHelpIcon,
  NewProviderIcon,
  RetryIcon,
  TestFailedIcon,
  TestPassedIcon,
} from "@/components/model-catalog/icons"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Field,
  FieldDescription,
  FieldLabel,
  FieldSeparator,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import { Textarea } from "@/components/ui/textarea"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  liveModelsFor,
  MODALITIES,
  PROVIDERS,
  providerById,
  type Modality,
} from "@/lib/model-catalog-data"
import { cn } from "@/lib/utils"

/**
 * Adding a model, in the two weights the PRD separates.
 *
 * Picking a model under a provider we already hold credentials for is the light
 * path: the key we already call that provider with fetches its own model list,
 * so there is nothing to configure. Connecting a provider we have never reached
 * is the heavy one: base URL, credentials, model identifier, and a connection
 * test that has to pass before the model can be saved.
 *
 * One entry point, two visibly different forms. The admin only discovers which
 * path they are on at the provider field — that is the moment they find out we
 * have never called this provider — so making them choose a flow beforehand
 * would ask a question they cannot yet answer. What the PRD's Braintrust
 * benchmark asks for is that the heavier action not be folded invisibly into
 * the lighter one, so the switch changes the dialog's title, adds a way back,
 * and splits the form into labelled sections the light path does not have.
 *
 * Modality is not a field. The catalog's tab decides it, and a select that
 * repeats the tab is one more place for the wrong value to be left at its
 * default.
 */

/** The sentinel the provider Select uses for "we have never called this one". */
const NEW_PROVIDER = "__new__"

/**
 * Placeholder examples per modality. A TTS voice-set caveat shown in the LLM
 * dialog is the kind of thing a reviewer reads as invented data, so every
 * example moves with the tab the dialog was opened from.
 */
const EXAMPLES: Record<Modality, { model: string; name: string }> = {
  llm: { model: "llama-3.3-70b-versatile", name: "Llama 3.3 70B" },
  tts: { model: "eleven_flash_v2_5", name: "ElevenLabs Flash v2.5" },
  stt: { model: "nova-3", name: "Deepgram Nova 3" },
}

type Mode = "pick" | "connect"
type FetchState = "idle" | "loading" | "ready" | "failed"
type TestState = "idle" | "running" | "passed" | "failed"

export function AddModelDialog({
  modality,
  onOpenChange,
  open,
}: {
  modality: Modality
  onOpenChange: (open: boolean) => void
  open: boolean
}) {
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      {/* The body is the only row that scrolls, so the header, the footer and
          the Save gate stay put however long the heavy path gets. */}
      <DialogContent className="grid-rows-[auto_1fr_auto] max-h-[85vh] sm:max-w-lg">
        <AddModelBody
          key={modality}
          modality={modality}
          onDone={() => onOpenChange(false)}
        />
      </DialogContent>
    </Dialog>
  )
}

function AddModelBody({
  modality,
  onDone,
}: {
  modality: Modality
  onDone: () => void
}) {
  const [mode, setMode] = React.useState<Mode>("pick")
  const [providerId, setProviderId] = React.useState("")
  const [modelId, setModelId] = React.useState("")
  const [displayName, setDisplayName] = React.useState("")
  const [notes, setNotes] = React.useState("")
  const [manual, setManual] = React.useState(false)
  const [fetchState, setFetchState] = React.useState<FetchState>("idle")
  const [testState, setTestState] = React.useState<TestState>("idle")

  /* Only the heavy path asks for these. */
  const [newProviderName, setNewProviderName] = React.useState("")
  const [baseUrl, setBaseUrl] = React.useState("")
  const [apiKey, setApiKey] = React.useState("")

  const modalityLabel =
    MODALITIES.find((option) => option.id === modality)?.label ?? ""
  const provider = providerById(providerId)
  const connecting = mode === "connect"
  const eligible = PROVIDERS.filter((option) =>
    option.modalities.includes(modality),
  )

  /* The live list is offered only where the provider publishes one and the
     fetch came back. Everything else — no endpoint, a fetch that timed out, or
     the admin choosing to type it — lands on the same manual field, because the
     answer in all three cases is "type the ID and prove it with a test". */
  const usesLiveList =
    !connecting &&
    provider?.listsModels === true &&
    !manual &&
    fetchState !== "failed"

  /* A model picked from a provider's own list is already proven by the list. A
     typed ID is not, and neither is a provider we have never called, so Save
     stays closed until the test passes. That gate is the whole guarantee the
     heavy path buys. */
  const testRequired = !usesLiveList && (connecting || Boolean(provider))
  const testReady = connecting
    ? Boolean(
        newProviderName.trim() && baseUrl.trim() && apiKey && modelId.trim(),
      )
    : Boolean(modelId.trim())

  const canSave =
    Boolean(modelId.trim()) &&
    Boolean(displayName.trim()) &&
    (connecting
      ? Boolean(newProviderName.trim() && baseUrl.trim() && apiKey)
      : Boolean(provider)) &&
    (!testRequired || testState === "passed")

  function selectProvider(next: string) {
    setModelId("")
    setManual(false)
    setTestState("idle")

    if (next === NEW_PROVIDER) {
      setMode("connect")
      setProviderId("")
      setFetchState("idle")
      return
    }

    setProviderId(next)

    const chosen = providerById(next)
    if (chosen?.listsModels) {
      setFetchState("loading")
      /* Groq is stubbed to fail so the fallback is reachable in the mockup
         rather than only described. */
      window.setTimeout(() => {
        setFetchState(chosen.id === "groq" ? "failed" : "ready")
      }, 900)
    } else {
      setFetchState("idle")
    }
  }

  function backToPicker() {
    setMode("pick")
    setProviderId("")
    setModelId("")
    setNewProviderName("")
    setBaseUrl("")
    setApiKey("")
    setTestState("idle")
    setFetchState("idle")
  }

  function runTest() {
    setTestState("running")
    /* A stub short ID fails, so both answers are reachable. */
    window.setTimeout(() => {
      setTestState(modelId.trim().length > 3 ? "passed" : "failed")
    }, 1100)
  }

  function save() {
    toast.success(`${displayName.trim()} added to the ${modalityLabel} catalog`)
    onDone()
  }

  return (
    <>
      <DialogHeader>
        {connecting ? (
          <Button
            className="-ms-2 self-start"
            onClick={backToPicker}
            size="xs"
            variant="ghost"
          >
            <BackToPickerIcon className="rtl:rotate-180" />
            Connected providers
          </Button>
        ) : null}

        <DialogTitle>
          {connecting ? "Connect a provider" : `Add ${modalityLabel} model`}
        </DialogTitle>
        <DialogDescription>
          {connecting
            ? "Adds the connection and its first model together."
            : `Adds it to the ${modalityLabel} picker in Global and Org Settings.`}
        </DialogDescription>
      </DialogHeader>

      {/* The ±1 pair gives focus rings room to draw inside the scroll box. */}
      <div className="-mx-1 flex min-h-0 flex-col gap-4 overflow-y-auto px-1 pb-1">
        {connecting ? (
          <>
            <Field>
              <FieldLabel htmlFor="provider-name">Provider name</FieldLabel>
              <Input
                id="provider-name"
                onChange={(event) => setNewProviderName(event.target.value)}
                placeholder="Fireworks"
                value={newProviderName}
              />
            </Field>

            <Field>
              <HelpLabel
                help="Must accept OpenAI-spec requests."
                htmlFor="base-url"
              >
                Base URL
              </HelpLabel>
              <Input
                id="base-url"
                onChange={(event) => {
                  setBaseUrl(event.target.value)
                  setTestState("idle")
                }}
                placeholder="https://api.fireworks.ai/inference/v1"
                value={baseUrl}
              />
            </Field>

            <Field>
              <FieldLabel htmlFor="api-key">API key</FieldLabel>
              <Input
                id="api-key"
                onChange={(event) => {
                  setApiKey(event.target.value)
                  setTestState("idle")
                }}
                placeholder="sk-…"
                type="password"
                value={apiKey}
              />
              {/* The one inline sentence in this dialog. A credential you
                  cannot read back is irreversible, which is the case the
                  helper-text rule keeps inline copy for. */}
              <FieldDescription>
                Stored once and never shown again.
              </FieldDescription>
            </Field>

            {/* A labelled rule rather than a heading: the form is doing two
                things, and a section title at the dialog title's own size
                would compete with it for the same job. */}
            <FieldSeparator>Model</FieldSeparator>

            <Field>
              <HelpLabel
                help="Sent to the provider exactly as typed."
                htmlFor="model"
              >
                Model identifier
              </HelpLabel>
              <Input
                id="model"
                onChange={(event) => {
                  setModelId(event.target.value)
                  setTestState("idle")
                }}
                placeholder={EXAMPLES[modality].model}
                value={modelId}
              />
            </Field>
          </>
        ) : (
          <>
            <Field>
              <FieldLabel htmlFor="provider">Provider</FieldLabel>
              <Select onValueChange={selectProvider} value={providerId}>
                <SelectTrigger className="w-full" id="provider">
                  <SelectValue placeholder="Pick a provider" />
                </SelectTrigger>
                <SelectContent>
                  {eligible.map((option) => (
                    <SelectItem key={option.id} value={option.id}>
                      {option.name}
                    </SelectItem>
                  ))}
                  <SelectSeparator />
                  {/* The heavier action, kept visibly apart from the
                      connections that already exist rather than sitting in
                      the same list as one more provider. */}
                  <SelectItem value={NEW_PROVIDER}>
                    <NewProviderIcon />
                    Connect a new provider…
                  </SelectItem>
                </SelectContent>
              </Select>
            </Field>

            {provider ? (
              <ModelField
                fetchState={fetchState}
                modelPlaceholder={EXAMPLES[modality].model}
                liveModels={liveModelsFor(provider.id, modality)}
                manual={manual}
                modelId={modelId}
                onManualChange={(next) => {
                  setManual(next)
                  setModelId("")
                  setTestState("idle")
                }}
                onModelIdChange={(next) => {
                  setModelId(next)
                  setTestState("idle")
                }}
                onRetryFetch={() => selectProvider(provider.id)}
                providerListsModels={provider.listsModels}
                providerName={provider.name}
                usesLiveList={usesLiveList}
              />
            ) : null}
          </>
        )}

        {testRequired ? (
          <ConnectionTest onRun={runTest} ready={testReady} state={testState} />
        ) : null}

        {connecting || provider ? (
          <>
            <FieldSeparator />

            <Field>
              <HelpLabel
                help="The name this model is picked by in settings."
                htmlFor="display-name"
              >
                Display name
              </HelpLabel>
              <Input
                id="display-name"
                onChange={(event) => setDisplayName(event.target.value)}
                placeholder={EXAMPLES[modality].name}
                value={displayName}
              />
            </Field>

            <Field>
              <FieldLabel htmlFor="notes">Notes (optional)</FieldLabel>
              <Textarea
                id="notes"
                onChange={(event) => setNotes(event.target.value)}
                placeholder="English only — Arabic calls must not be routed here."
                rows={2}
                value={notes}
              />
            </Field>
          </>
        ) : null}
      </div>

      <DialogFooter>
        <Button onClick={onDone} variant="ghost">
          Cancel
        </Button>
        <Button disabled={!canSave} onClick={save}>
          Add model
        </Button>
      </DialogFooter>
    </>
  )
}

/**
 * A label with an (i) for the one thing about the field its own name cannot
 * carry. One sentence, and never a restatement of the label — anything that
 * needs a paragraph is a design problem, not a copy problem.
 */
function HelpLabel({
  children,
  help,
  htmlFor,
}: {
  children: string
  help: string
  htmlFor: string
}) {
  return (
    <div className="flex items-center gap-1.5">
      <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      <Tooltip>
        <TooltipTrigger
          aria-label={`About ${children}`}
          className="text-muted-foreground hover:text-foreground"
        >
          <FieldHelpIcon className="size-3.5" />
        </TooltipTrigger>
        <TooltipContent className="max-w-64">{help}</TooltipContent>
      </Tooltip>
    </div>
  )
}

/**
 * The model field, in whichever of its shapes applies.
 *
 * The switch is automatic: a provider that publishes a list gets the list. The
 * manual escape stays reachable underneath it regardless, because a live list
 * lags a provider's own releases and an admin who already knows the new ID
 * should not have to wait for the list to catch up.
 */
function ModelField({
  fetchState,
  liveModels,
  manual,
  modelId,
  modelPlaceholder,
  onManualChange,
  onModelIdChange,
  onRetryFetch,
  providerListsModels,
  providerName,
  usesLiveList,
}: {
  fetchState: FetchState
  liveModels: string[]
  manual: boolean
  modelId: string
  modelPlaceholder: string
  onManualChange: (manual: boolean) => void
  onModelIdChange: (modelId: string) => void
  onRetryFetch: () => void
  providerListsModels: boolean
  providerName: string
  usesLiveList: boolean
}) {
  if (fetchState === "loading") {
    return (
      <Field>
        <FieldLabel>Model</FieldLabel>
        <div className="flex h-8 items-center gap-2 rounded-lg bg-muted px-3 text-sm text-muted-foreground">
          <Spinner />
          Fetching {providerName}&apos;s models…
        </div>
      </Field>
    )
  }

  return (
    <Field>
      {fetchState === "failed" ? (
        /* A fetch that timed out says nothing about whether the model is
           valid, so this is a notice with a way forward, not an error. */
        <Alert>
          <FetchWarningIcon />
          <AlertTitle>
            Couldn&apos;t reach {providerName}&apos;s model list
          </AlertTitle>
          <AlertDescription>
            Enter the model ID and test it instead.
          </AlertDescription>
        </Alert>
      ) : null}

      <div className="flex items-center gap-2">
        {usesLiveList ? (
          <>
            <FieldLabel htmlFor="model">Model</FieldLabel>
            {/* Provenance in three words rather than the two-line paragraph
                this used to carry. */}
            <Badge variant="outline">Live from {providerName}</Badge>
          </>
        ) : (
          <HelpLabel
            help="Sent to the provider exactly as typed."
            htmlFor="model"
          >
            Model identifier
          </HelpLabel>
        )}
      </div>

      {usesLiveList ? (
        <Select onValueChange={onModelIdChange} value={modelId}>
          <SelectTrigger className="w-full" id="model">
            <SelectValue placeholder="Pick a model" />
          </SelectTrigger>
          <SelectContent>
            {liveModels.map((option) => (
              <SelectItem key={option} value={option}>
                {option}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          id="model"
          onChange={(event) => onModelIdChange(event.target.value)}
          placeholder={modelPlaceholder}
          value={modelId}
        />
      )}

      {/* An escape, not an explainer: every one of these is an action the admin
          can take when the field in front of them is the wrong one. */}
      {/* `Field` puts `*:w-full` on its direct children, so a button that
          should hug its own text stretches and centres. The wrapper takes the
          full width and lets the button keep its intrinsic one. */}
      <div className="flex">
        {usesLiveList ? (
          <Button onClick={() => onManualChange(true)} size="xs" variant="link">
            Not seeing it? Enter the ID manually
          </Button>
        ) : fetchState === "failed" ? (
          <Button onClick={onRetryFetch} size="xs" variant="outline">
            <RetryIcon />
            Try the list again
          </Button>
        ) : manual && providerListsModels ? (
          <Button
            onClick={() => onManualChange(false)}
            size="xs"
            variant="link"
          >
            Back to {providerName}&apos;s list
          </Button>
        ) : null}
      </div>
    </Field>
  )
}

/**
 * The connection test.
 *
 * It gates Save on the paths where nothing else proves the model exists — a
 * provider we have never called, or an ID typed by hand. On the live-list path
 * it is absent entirely, because picking from the provider's own list already
 * is the proof.
 */
function ConnectionTest({
  onRun,
  ready,
  state,
}: {
  onRun: () => void
  ready: boolean
  state: TestState
}) {
  const passed = state === "passed"
  const failed = state === "failed"

  return (
    <div className="flex flex-col gap-3 rounded-lg bg-muted p-3">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">Connection test</span>
          {/* One word in place of the sentence that used to say Save is
              blocked — the disabled Save button already says that. */}
          <Badge variant="outline">Required</Badge>
        </div>
        <Button
          disabled={!ready || state === "running"}
          onClick={onRun}
          size="sm"
          variant="outline"
        >
          {state === "running" ? <Spinner /> : null}
          {state === "running" ? "Testing…" : passed ? "Test again" : "Test"}
        </Button>
      </div>

      {passed || failed ? (
        <div className="flex items-start gap-2 rounded-lg bg-card p-3 text-sm">
          {passed ? (
            <TestPassedIcon className="mt-0.5 size-4 shrink-0 text-success" />
          ) : (
            <TestFailedIcon className="mt-0.5 size-4 shrink-0 text-destructive" />
          )}
          <span className={cn(!passed && "text-foreground")}>
            {passed
              ? "The provider answered in 412 ms."
              : "The provider rejected that model ID — check it against their own documentation."}
          </span>
        </div>
      ) : null}
    </div>
  )
}

